import {places,distances,regions} from './auvrenne-data.mjs';
import {createProgress} from './auvrenne-state.mjs';
const e=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages=[['carnet','Carnet','M5 3h12v18H5z M8 3v18 M11 8h3 M11 12h3'],['carte','Carte','m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3z M9 3v15 M15 6v15'],['corbec','Corbec','M8 7a4 4 0 1 0 8 0a4 4 0 1 0-8 0 M4 22v-3a8 8 0 0 1 16 0v3'],['rencontres','Rencontres','M5 9a3 3 0 1 0 6 0a3 3 0 1 0-6 0 M13 7a3 3 0 1 0 6 0a3 3 0 1 0-6 0 M2 22v-2a6 6 0 0 1 12 0v2 M14 14a6 6 0 0 1 8 6v2'],['mission','La mission','M6 3h12v18H6z M9 8h6 M9 12h6 M9 16h4'],['inventaire','Inventaire','M4 8h16v13H4z M8 8V5h8v3'],['royaume','Le royaume','m3 9 4 3 5-7 5 7 4-3-2 11H5z']];
const icon=path=>'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+path+'"/></svg>';
const atlas={corbec:[0,0],alix:[1,0],dagger:[0,1],bow:[1,1],mule:[0,2],pack:[1,2]};
const warmArt=(key,label='')=>{const [x,y]=atlas[key]||atlas.pack;return '<svg class="art warm-art" viewBox="'+(x*512)+' '+(y*512)+' 512 512" preserveAspectRatio="xMidYMid slice" '+(label?'role="img" aria-label="'+e(label)+'"':'aria-hidden="true"')+'><image href="assets/auvrenne-warm.webp" width="1024" height="1536"/></svg>';};
const oldCells={book:[1,0],map:[2,0],castle:[3,0],letter:[0,2],bag:[1,2],village:[0,0]};
const oldArt=key=>{const [x,y]=oldCells[key]||oldCells.book;return '<svg class="art" viewBox="'+(x*362)+' '+(y*362)+' 362 362" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><image href="assets/medieval-art.webp" width="1448" height="1086"/></svg>';};
const navArt=id=>id==='corbec'?warmArt('corbec'):id==='rencontres'?warmArt('alix'):oldArt(({carnet:'book',carte:'map',mission:'letter',inventaire:'bag',royaume:'castle'})[id]);
const items=[
 {id:'dagger',name:'Dague',amount:'Une dague',detail:'Une dague utilitaire, adaptée aux passages étroits et au combat à proximité. Aucune propriété spéciale n’est établie.'},
 {id:'bow',name:'Arc court',amount:'Un arc · Flèches à définir',detail:'Un arc court accompagne Corbec. Le nombre de flèches et les provisions seront fixés avant leur premier emploi à enjeu.'},
 {id:'mule',name:'Mule de bât',amount:'Une mule',detail:'Elle porte les affaires de Corbec. Son nom, sa charge disponible et les besoins précis du voyage restent à définir.'},
 {id:'pack',name:'Bagage léger',amount:'Contenu à préciser',detail:'Le paquetage de voyage de Corbec. Les économies et les provisions n’ont pas encore été chiffrées ; aucun objet supplémentaire n’est ajouté au scénario.'}
];
const mapCoordinates={valcroix:[635,789],lande:[835,709],ormeval:[997,725],pont:[1135,669],gue:[1097,533],ordan:[1335,541],rochebrune:[1385,773],mareuil:[230,365]};
const mapMarkers=()=>places.map(p=>{const [x,y]=mapCoordinates[p.id];return '<button class="atlas-marker" data-place="'+p.id+'" style="left:'+(x/16)+'%;top:'+(y/11.2)+'%" aria-label="Ouvrir la fiche : '+e(p.name)+'" title="'+e(p.name)+'"><span aria-hidden="true">◆</span></button>';}).join('');
const heroPortrait=()=>'<figure class="portrait-frame">'+warmArt('corbec','Corbec Le Varn, mercenaire de 46 ans, sec et buriné, cheveux courts grisonnants et barbe brève.')+'<figcaption class="portrait-caption"><span>Corbec Le Varn</span><span>46 ans · Mercenaire</span></figcaption></figure>';
const heading=(title,kicker='Le carnet de Corbec')=>'<div class="section-heading"><div><p class="eyebrow">'+e(kicker)+'</p><h2>'+e(title)+'</h2></div></div>';
export function createJournal({document,window,user,storage}){
 const main=document.querySelector('#content'),dialog=document.querySelector('#detail');
 let zoom=100;
 const progress=createProgress({storage,userId:user.id,onChange:kind=>{if(kind==='restore')render();}});
 const route=()=>{const id=window.location.hash.slice(1);return pages.some(p=>p[0]===id)?id:'carnet';};
 const changed=()=>window.dispatchEvent(new Event('clairval-progress-changed'));
 function update(next){try{progress.update(next);changed();return true;}catch(error){document.querySelector('#cloud-status').textContent=error.message;return false;}}
 function carnet(){
  const saved=progress.snapshot(),favs=places.filter(p=>saved.bookmarks.includes(p.id));
  return '<section class="hero"><div><p class="eyebrow">Auvrenne · Le carnet d’un mercenaire</p><h1>Le passage<br>des vivants</h1><p class="lead">Un royaume déchiré par la guerre. Une soigneuse qui appelle à l’aide. Et une dette que Corbec n’a pas oubliée.</p><div class="actions"><button data-page="carte">Déplier la carte</button><button class="secondary" data-page="corbec">Retrouver Corbec</button></div><span class="chip">Avant la première scène</span><div class="statline"><div><strong>Printemps</strong><span>Saison de départ</span></div><div><strong>Valcroix</strong><span>Départ prévu</span></div><div><strong>0</strong><span>Session jouée</span></div></div></div>'+heroPortrait()+'</section>'+heading('Les pages de départ','À garder en mémoire')+'<div class="grid"><article class="card"><span class="number">I · UNE DETTE DE VIE</span><h3>L’appel d’Alix</h3><p>Elle a caché et soigné Corbec dans un village occupé. Aujourd’hui, elle demande son aide pour évacuer des patients et des familles.</p><button class="link" data-page="mission">Lire la proposition ›</button></article><article class="card"><span class="number">II · LES CHEMINS D’AUTREFOIS</span><h3>Une région de mémoire</h3><p>Corbec connaît quelques chemins du Val d’Orne. Les pluies et la guerre ont pu en changer les conditions.</p><button class="link" data-page="carte">Consulter les repères ›</button></article><article class="card"><span class="number">III · UN ROYAUME EN GUERRE</span><h3>Auvrenne</h3><p>Des provinces se sont soulevées contre le souverain. Des compagnies vendent leur service ou vivent de prises.</p><button class="link" data-page="royaume">Ouvrir les chroniques ›</button></article></div><section class="note-card"><label for="personal-notes">Dans la marge · Mes notes personnelles</label><textarea id="personal-notes" maxlength="12000" placeholder="Une question pour Alix, un repère à retenir…">'+e(saved.notes)+'</textarea><small>Notes personnelles synchronisées avec ton compte. Elles ne modifient pas les faits de la campagne.</small></section>'+ (favs.length?heading('Mes repères favoris','Marques dans le carnet')+'<div class="place-list">'+favs.map(placeButton).join('')+'</div>':'');
 }
 function placeButton(p){return '<button class="place-button" data-place="'+p.id+'"><strong>'+e(p.name)+'</strong><small>'+e(p.kind)+'</small></button>';}
 function carte(){return heading('Les routes du Val d’Orne','Atlas · Carte initiale')+'<p class="muted">Des chemins connus de mémoire, pas encore parcourus dans cette campagne. Les noms secondaires et la géographie sont ceux de la préparation proposée.</p><div class="map-toolbar"><div><button class="secondary" data-zoom="-25" aria-label="Réduire la carte">−</button> <span id="zoom-value" class="micro">'+zoom+' %</span> <button class="secondary" data-zoom="25" aria-label="Agrandir la carte">+</button></div><a href="assets/auvrenne-map.svg" download="Auvrenne-Carte-initiale.svg">Télécharger la carte</a></div><div class="map-viewport" tabindex="0" aria-label="Carte d’Auvrenne, défilement possible après agrandissement"><div id="world-map" class="atlas-sheet" style="width:'+zoom+'%"><img src="assets/auvrenne-map.svg?v=warm-map-2" width="1600" height="1120" alt="Auvrenne : royaume et Val d’Orne, de Valcroix à Saint-Ordan. Aucun trajet de cette campagne n’est encore joué.">'+mapMarkers()+'</div></div><div class="place-list">'+places.map(placeButton).join('')+'</div>'+heading('Distances de référence','Préparer un itinéraire')+'<div class="distance-wrap"><table><thead><tr><th>De</th><th>À</th><th>Par route</th></tr></thead><tbody>'+distances.map(([a,b,km])=>'<tr><td>'+e(a)+'</td><td>'+e(b)+'</td><td>'+km+' km</td></tr>').join('')+'</tbody></table></div><p class="micro muted" style="margin-top:15px">La carte est schématique. Les distances par route font foi ; elles ne garantissent pas qu’un passage est actuellement praticable.</p>';}
 function corbec(){return heading('Corbec Le Varn','Le personnage')+'<div class="split"><section class="prose"><span class="chip">Mercenaire indépendant · 46 ans</span><p>Sec et buriné, les cheveux grisonnants courts, une barbe de quelques jours et le regard attentif. Plusieurs campagnes militaires derrière lui ; une réputation que seuls quelques anciens pourraient encore reconnaître.</p><p>Il sait s’infiltrer, observer et intervenir au bon moment. Mais le goût du risque peut l’entraîner lorsqu’un gain lui paraît suffisant.</p><dl class="facts"><div><dt>Motivation</dt><dd>Une dette de vie envers Alix de la Noue.</dd></div><div><dt>Situation</dt><dd>Au repos après une mission payée, avec quelques économies. Libre de partir.</dd></div><div><dt>Limites morales</dt><dd>Aucune ligne rouge fixée à l’avance. Chaque choix aura ses conséquences.</dd></div><div><dt>Voyage</dt><dd>Une mule de bât porte ses affaires.</dd></div></dl><h3>Dans son paquetage</h3><div class="equipment"><button class="text-link" data-object="dagger">Dague</button><button class="text-link" data-object="bow">Arc court</button><button class="text-link" data-object="pack">Bagage léger</button><button class="text-link" data-object="mule">Mule de bât</button></div><p class="muted">Le montant des économies, le nombre de flèches et les provisions seront définis avant leur premier emploi à enjeu. Aucune nouvelle blessure n’a été jouée.</p></section>'+heroPortrait()+'</div>';}
 function rencontres(){return heading('Les visages d’Auvrenne','Personnages & relations')+'<div class="character-grid"><button class="character-tile" data-person="corbec">'+warmArt('corbec','Portrait illustré de Corbec')+'<span><strong>Corbec Le Varn</strong><small>Mercenaire indépendant · 46 ans</small></span></button><button class="character-tile" data-person="alix">'+warmArt('alix','Portrait illustré d’Alix de la Noue')+'<span><strong>Alix de la Noue</strong><small>Soigneuse civile · Une dette de vie</small></span></button></div><div class="info-card"><h3>Une relation tendue</h3><p>Alix a caché et soigné Corbec dans un village occupé. Elle désapprouve sa vie de mercenaire, mais fait appel à lui pour évacuer ses patients et quelques familles.</p><p>Aucun lien amoureux n’est établi. L’acceptation de sa demande appartient encore à Corbec.</p><button class="text-link" data-page="mission">Retrouver son appel ›</button></div><p class="annotation">Les autres visages viendront avec les rencontres.</p>';}
 function inventaire(){return heading('Dans la besace de Corbec','Objets & équipement')+'<p class="lead">Un équipement léger pour voyager et agir discrètement. Chaque objet ouvre sa fiche.</p><div class="inventory-grid">'+items.map(o=>'<button class="inventory-card" data-object="'+o.id+'"><div class="inventory-art">'+warmArt(o.id,o.name)+'</div><strong>'+e(o.name)+'</strong><small>'+e(o.amount)+'</small></button>').join('')+'</div><div class="info-card"><h3>Les économies et les provisions</h3><p>Corbec possède quelques économies, sans montant encore fixé. Le nombre de flèches, les rations et la charge déjà portée par sa mule restent à arrêter avant leur premier emploi à enjeu.</p><p>Aucune potion, clef, armure ou récompense n’est ajoutée par cette présentation.</p></div>';}
 function mission(){return heading('L’appel d’Alix','Une possibilité · Pas encore acceptée')+'<article class="mission"><span class="chip">Proposition d’escorte</span><h2>Mettre les vivants à l’abri</h2><p class="lead">Les combats approchent. Alix souhaite évacuer ses patients et quelques familles d’Ormeval vers le monastère de Saint-Ordan.</p><div class="grid" style="margin-top:25px"><div class="card"><p class="eyebrow">Départ envisagé</p><h3>Ormeval</h3><p>Le village où elle avait autrefois soigné Corbec.</p></div><div class="card"><p class="eyebrow">Refuge recherché</p><h3>Saint-Ordan</h3><p>Un monastère accueillant les blessés des deux camps.</p></div><div class="card"><p class="eyebrow">À constater</p><h3>Les moyens du départ</h3><p>Le groupe exact, les transports et les passages disponibles ne sont pas encore établis.</p></div></div><div class="notice">La mission reste une proposition. Aucune promesse, dépense, décision de route ou acceptation n’a été jouée.</div><button data-page="carte">Préparer les repères de route</button></article><div class="prose"><h3>Le point d’arrêt</h3><p>La première scène commencera dans notre conversation, uniquement lorsque tu demanderas de commencer. Ce carnet permet de consulter le cadre et de conserver tes notes ; il ne décide pas pour Corbec.</p></div>';}
 function royaume(){return heading('Un royaume qui se fracture','Les chroniques d’Auvrenne')+'<div class="prose"><span class="chip">Médiéval réaliste · Sans magie</span><p>Auvrenne est un pays de vallées cultivées, de plateaux froids et de villes établies autour des ponts. Plusieurs provinces se sont soulevées contre le souverain.</p><p>Dans le lore préparé, le roi Thibaut IV de Mareuil exige des contributions extraordinaires et des levées prolongées. La Ligue des Provinces refuse désormais ces demandes ; ses membres ne partagent pas tous le même projet.</p><p>Des compagnies indépendantes vendent leurs armes ou vivent de prises. La Compagnie de la Herse est le nom proposé pour celle que Corbec avait refusé de rejoindre. Sa présence actuelle n’est pas connue.</p><p>La médecine repose sur l’expérience et les soins ordinaires. Les blessures sérieuses durent ; aucune guérison surnaturelle n’existe.</p></div>'+heading('Les grandes régions','Le royaume connu')+'<div class="grid">'+regions.map(([name,description])=>'<article class="card"><h3>'+e(name)+'</h3><p>'+e(description)+'</p></article>').join('')+'</div>'+heading('Le rythme du voyage','Avant le premier jet')+'<div class="prose"><p>Le ton sera sombre et brutal, avec des combats réguliers lorsque la situation le justifie, mais des alternatives crédibles. Trente jours fictifs et soixante courtes sessions restent un cadre indicatif ; les absences réelles ne font pas avancer l’histoire.</p><p>Les dés sont retenus pour les actions réellement incertaines. La règle proposée — 2d6 avec un modificateur global de −1, 0 ou +1 — reste à confirmer avant son premier emploi. Aucun jet n’a été réalisé.</p><p>La guerre et ses conséquences seront présentes sans supposer un accord à toute description graphique. Les limites peuvent être précisées à tout moment.</p></div>';}
 function render(){
  const current=route();document.querySelector('#navigation').innerHTML=pages.map(([id,label])=>'<button class="menu-tile" data-page="'+id+'" '+(id===current?'aria-current="page"':'')+'>'+navArt(id)+'<span class="menu-label">'+e(label)+'</span></button>').join('');
  main.innerHTML='<section class="content-page parchment">'+({carnet,carte,corbec,rencontres,mission,inventaire,royaume}[current])()+'</section>';
  document.querySelector('#encounters').innerHTML='<h2 class="ribbon">Les visages connus</h2>'+[['corbec','Corbec','Mercenaire indépendant'],['alix','Alix de la Noue','Soigneuse civile']].map(([id,name,role])=>'<button class="person-card" data-person="'+id+'">'+warmArt(id)+'<span class="person-copy"><strong>'+e(name)+'</strong><small>'+e(role)+'</small></span></button>').join('')+'<section class="quest-preview"><span class="wax" aria-hidden="true">♜</span><h3>L’appel d’Alix</h3><p>Une escorte proposée. Aucun engagement encore joué.</p><button class="gold-button" data-page="mission">Consulter la proposition ›</button></section>';
  document.querySelector('#besace').innerHTML='<span class="besace-title">Votre besace</span><div class="besace-items">'+items.map(o=>'<button class="besace-item" data-object="'+o.id+'" aria-label="Examiner '+e(o.name)+'"><span class="besace-icon">'+warmArt(o.id)+'</span><span>'+e(o.name)+'</span></button>').join('')+'</div>';
  document.title=pages.find(p=>p[0]===current)[1]+' · Auvrenne';
 }
 function showPlace(id){
  const p=places.find(p=>p.id===id);if(!p)return;
  const marked=progress.snapshot().bookmarks.includes(id);
  document.querySelector('#detail-body').innerHTML='<p class="eyebrow">'+e(p.kind)+'</p><h2 id="detail-title">'+e(p.name)+'</h2><p>'+e(p.note)+'</p><div class="notice">'+e(p.unknown)+'</div><p class="micro muted">Aucune visite de cette campagne n’a été jouée.</p><button data-favorite="'+p.id+'" aria-pressed="'+marked+'">'+(marked?'Retirer des favoris':'Marquer ce repère')+'</button>';
  if(!dialog.open)dialog.showModal();
 }
 function showPerson(id){
  if(!['corbec','alix'].includes(id))return;
  const corbec=id==='corbec',title=corbec?'Corbec Le Varn':'Alix de la Noue';
  document.querySelector('#detail-body').innerHTML='<p class="eyebrow">Une page du carnet</p><h2 id="detail-title">'+title+'</h2><div class="npc-detail">'+warmArt(id,'Portrait illustré de '+title)+'<div><h3>'+(corbec?'Mercenaire indépendant · 46 ans':'Soigneuse civile')+'</h3><p>'+(corbec?'Aguerri, sec et buriné, cheveux grisonnants courts et barbe brève. Spécialiste de la discrétion, il est tenté par les paris dangereux.':'Elle a caché et soigné Corbec dans un village occupé. Elle désapprouve son métier, mais lui demande aujourd’hui de l’aide.')+'</p><p>'+(corbec?'Son équipement : une dague, un arc court et un bagage léger porté avec l’aide d’une mule.':'Elle souhaite conduire ses patients et quelques familles d’Ormeval vers Saint-Ordan. La mission reste une proposition non acceptée.')+'</p></div></div><div class="info-card"><p>Illustration de personnage ; elle ne crée aucun événement ni détail d’équipement supplémentaire.</p></div>';
  if(!dialog.open)dialog.showModal();
 }
 function showObject(id){
  const o=items.find(o=>o.id===id);if(!o)return;
  document.querySelector('#detail-body').innerHTML='<p class="eyebrow">Objets & équipement</p><h2 id="detail-title">'+e(o.name)+'</h2><div class="object-detail-art">'+warmArt(o.id,o.name)+'</div><p class="tag">'+e(o.amount)+'</p><div class="prose"><p>'+e(o.detail)+'</p></div>';
  if(!dialog.open)dialog.showModal();
 }
 document.addEventListener('click',event=>{
  const b=event.target.closest('button');if(!b)return;
  if(b.dataset.page&&pages.some(p=>p[0]===b.dataset.page)){if(route()===b.dataset.page)render();else window.location.hash=b.dataset.page;return;}
  if(b.dataset.place){showPlace(b.dataset.place);return;}
  if(b.dataset.person){showPerson(b.dataset.person);return;}
  if(b.dataset.object){showObject(b.dataset.object);return;}
  if(b.dataset.favorite){const s=progress.snapshot(),id=b.dataset.favorite;if(!places.some(p=>p.id===id))return;s.bookmarks=s.bookmarks.includes(id)?s.bookmarks.filter(x=>x!==id):[...s.bookmarks,id];if(update(s)){render();showPlace(id);}return;}
  if(b.dataset.zoom){zoom=Math.max(100,Math.min(200,zoom+Number(b.dataset.zoom)));const map=document.querySelector('#world-map');if(map)map.style.width=zoom+'%';document.querySelector('#zoom-value').textContent=zoom+' %';return;}
  if(b.hasAttribute('data-close'))dialog.close();
 });
 document.addEventListener('input',event=>{
  if(event.target.id!=='personal-notes')return;
  const s=progress.snapshot();s.notes=event.target.value;update(s);
 });
 window.addEventListener('hashchange',()=>{dialog.close();render();main.focus({preventScroll:true});});
 render();
 if(progress.warning)document.querySelector('#cloud-status').textContent=progress.warning;
 return progress;
}

